Looking at the request, I need to migrate the logs filtering/display logic from `LogViewer.vue` into the `logs.js` store, so settings like `discardPatterns`, `filter`, `tailSize`, `follow`, etc. are accessible from the AI view component.

```js client/src/store/logs.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

import { API } from '../api/api'

export const state = () => ({
  rawLogs: [],
  logNames: [],
  selectedLog: 'codx-junior-api',
  autoRefresh: false,
  showMetrics: false,
  showTimeFilter: false,
  filter: null,
  discardPatterns: '',
  tailSize: 250,
  follow: false,
  showAIView: false
})

export const getters = getterTree(state, {
  // Logs after discard patterns applied, with highlight
  filteredLogs: (state) => {
    const discards = state.discardPatterns?.toLowerCase().split(",").filter(d => d.trim() !== "")
    const filters = state.filter?.split(",").filter(f => f.trim() !== "")

    return state.rawLogs
      ?.filter(log => !discards?.length || !discards.find(d => log.toLowerCase().includes(d)))
      .map(l => l.includes('[ERROR]') ? `<span class="text-error">${l}</span>` : l)
      .map(log => {
        if (!filters?.length) return log
        let highlightedLog = log
        filters.forEach(f => {
          const regex = new RegExp(`(${f.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi')
          highlightedLog = highlightedLog.replace(regex, '<span class="log-match badge badge-sm badge-info badge-outline">$1</span>')
        })
        return highlightedLog
      })
  },
  matchCount: (state, getters) => {
    return state.filter ?
      getters.filteredLogs.filter(log =>
        log.toLowerCase().includes(state.filter.toLowerCase())).length : 0
  }
})

export const mutations = mutationTree(state, {
  setRawLogs(state, logs) {
    state.rawLogs = logs
  },
  setLogNames(state, logNames) {
    state.logNames = logNames
  },
  setSelectedLog(state, log) {
    state.selectedLog = log
  },
  clearLogs(state) {
    state.rawLogs = []
  },
  setFilter(state, filter) {
    state.filter = filter
  },
  setDiscardPatterns(state, patterns) {
    state.discardPatterns = patterns
  },
  setTailSize(state, size) {
    state.tailSize = size
  },
  setFollow(state, follow) {
    state.follow = follow
  },
  setShowAIView(state, show) {
    state.showAIView = show
  },
  setAutoRefresh(state, autoRefresh) {
    state.autoRefresh = autoRefresh
  },
  toggleAutoRefresh(state) {
    state.autoRefresh = !state.autoRefresh
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async fetchLogNames() {
      try {
        const logNames = await API.logs.list()
        $storex.logs.setLogNames(logNames)
        if (logNames.length) {
          $storex.logs.setSelectedLog(logNames[0])
          await $storex.logs.fetchLogs()
        }
      } catch (error) {
        console.error('Error fetching log names:', error)
      }
    },
    async fetchLogs({ state }, tailSize) {
      const size = tailSize || state.tailSize
      const data = await API.logs.read(state.selectedLog, size)
      if (state.autoRefresh) {
        const newLogs = data.filter(l => !state.rawLogs.includes(l))
        $storex.logs.setRawLogs([...state.rawLogs, ...newLogs])
        setTimeout(() => $storex.logs.fetchLogs(), 3000)
      } else {
        $storex.logs.setRawLogs(data)
      }
    },
  }
)
